pub type Range = enum {
  Between(lo: Int, hi: Int),
}

fn contains(r: &Range, n: Int) -> Bool {
  match r {
    Between(lo, hi) if n >= lo && n <= hi => { return true; }
    Between(_, _) => { return false; }
  }
}

fn width(r: &Range) -> Int {
  match r {
    Between(lo, hi) => { return hi - lo; }
  }
}

fn main() -> Int {
  let r = Range.Between(10, 20);
  if contains(&r, 15) {
    return width(&r);
  }
  return 0;
}
